INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0206-0001-0001-000000000001', '22222222-0002-0001-0001-000000000006', 'Navigating the x-y Plane', 'Master all four quadrants of the coordinate plane', 1, 'tutorial', 15, 5, 1637, 'René Descartes',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0206-0001-0001-000000000001', '33333333-0206-0001-0001-000000000001', 'multiple_choice', 'easy', 'How many quadrants does the coordinate plane have?', NULL, '[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"6"}]'::jsonb, '"c"'::jsonb, 'The x-axis and y-axis divide the plane into 4 quadrants, numbered I through IV counterclockwise from the top-right.', 'The two axes create four sections', 5, 1),
('44444444-0206-0001-0001-000000000002', '33333333-0206-0001-0001-000000000001', 'multiple_choice', 'easy', 'In which quadrant are BOTH coordinates negative?', NULL, '[{"id":"a","text":"Quadrant I"},{"id":"b","text":"Quadrant II"},{"id":"c","text":"Quadrant III"},{"id":"d","text":"Quadrant IV"}]'::jsonb, '"c"'::jsonb, 'Quadrant III is the bottom-left corner where both x and y are negative.', 'Both negative = left AND down', 5, 2),
('44444444-0206-0001-0001-000000000003', '33333333-0206-0001-0001-000000000001', 'fill_in_blank', 'easy', 'The point (-5, 3) has a negative x and positive y. Which quadrant is it in? (Type just the number)', NULL, NULL, '"2"'::jsonb, 'Negative x = left, positive y = up. That is the top-left area = Quadrant II.', 'Left + up = which quadrant?', 5, 3),
('44444444-0206-0001-0001-000000000004', '33333333-0206-0001-0001-000000000001', 'true_false', 'easy', 'True or False: A point on the x-axis always has y = 0.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Points on the x-axis have no vertical displacement, so y = 0. Examples: (3, 0), (-2, 0), (0, 0).', 'If you are ON the axis, you have not moved up or down', 5, 4),
('44444444-0206-0001-0001-000000000005', '33333333-0206-0001-0001-000000000001', 'multiple_choice', 'easy', 'What is the coordinate of the center of the plane where the axes cross?', NULL, '[{"id":"a","text":"(1, 1)"},{"id":"b","text":"(0, 0)"},{"id":"c","text":"(0, 1)"},{"id":"d","text":"(1, 0)"}]'::jsonb, '"b"'::jsonb, 'The center where both axes cross is the origin: (0, 0). Zero horizontal, zero vertical.', 'No movement in either direction = both zero', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0206-0001-0001-000000000002', '22222222-0002-0001-0001-000000000006', 'Plotting in All Quadrants', 'Place points accurately in all four quadrants', 2, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0206-0002-0001-000000000001', '33333333-0206-0001-0001-000000000002', 'multiple_choice', 'easy', 'Where would you plot the point (-4, -2)?', NULL, '[{"id":"a","text":"4 right, 2 up"},{"id":"b","text":"4 left, 2 up"},{"id":"c","text":"4 left, 2 down"},{"id":"d","text":"4 right, 2 down"}]'::jsonb, '"c"'::jsonb, 'Negative x = left (4 units), negative y = down (2 units). The point is in Quadrant III.', 'Both negative = both go in the negative direction', 5, 1),
('44444444-0206-0002-0001-000000000002', '33333333-0206-0001-0001-000000000002', 'fill_in_blank', 'easy', 'You start at the origin. Move 3 units right and 6 units down. What is the y-coordinate of your position?', NULL, NULL, '"-6"'::jsonb, 'Down from the origin means negative y. Moving 6 units down gives y = -6. Your position is (3, -6).', 'Down = negative', 5, 2),
('44444444-0206-0002-0001-000000000003', '33333333-0206-0001-0001-000000000002', 'multiple_choice', 'easy', 'Which of these points is in Quadrant I?', NULL, '[{"id":"a","text":"(-2, 5)"},{"id":"b","text":"(3, -1)"},{"id":"c","text":"(-4, -3)"},{"id":"d","text":"(5, 7)"}]'::jsonb, '"d"'::jsonb, 'Quadrant I has both coordinates positive. Only (5, 7) has x > 0 AND y > 0.', 'Quadrant I = both positive', 5, 3),
('44444444-0206-0002-0001-000000000004', '33333333-0206-0001-0001-000000000002', 'true_false', 'easy', 'True or False: The point (0, -5) is on the y-axis.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! When x = 0, the point is on the y-axis regardless of the y value. (0, -5) is 5 units below the origin, sitting right on the y-axis.', 'x = 0 means no horizontal movement', 5, 4),
('44444444-0206-0002-0001-000000000005', '33333333-0206-0001-0001-000000000002', 'fill_in_blank', 'easy', 'How many units apart are the points (2, 0) and (8, 0)? (Type just the number)', NULL, NULL, '"6"'::jsonb, 'Both are on the x-axis (y = 0). Distance = 8 - 2 = 6 units. Easy when the points share a coordinate!', 'Both are on the x-axis — just subtract the x values', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0206-0001-0001-000000000003', '22222222-0002-0001-0001-000000000006', 'Distance Between Points', 'Calculate how far apart two points are', 3, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0206-0003-0001-000000000001', '33333333-0206-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is the distance between (1, 3) and (1, 9)?', NULL, NULL, '"6"'::jsonb, 'Same x-coordinate, so the distance is just the difference in y: |9 - 3| = 6.', 'Same x = vertical distance only', 5, 1),
('44444444-0206-0003-0001-000000000002', '33333333-0206-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is the distance between (-3, 0) and (5, 0)?', NULL, NULL, '"8"'::jsonb, 'Both on the x-axis. Distance = |5 - (-3)| = |5 + 3| = 8.', 'Both on the x-axis — subtract x values (watch the negative!)', 5, 2),
('44444444-0206-0003-0001-000000000003', '33333333-0206-0001-0001-000000000003', 'multiple_choice', 'medium', 'What is the distance between (0, 0) and (3, 4)?', NULL, '[{"id":"a","text":"5"},{"id":"b","text":"7"},{"id":"c","text":"12"},{"id":"d","text":"25"}]'::jsonb, '"a"'::jsonb, 'Use the Pythagorean theorem: √(3² + 4²) = √(9 + 16) = √25 = 5. This is the famous 3-4-5 right triangle!', 'Think of a right triangle with legs 3 and 4', 10, 3),
('44444444-0206-0003-0001-000000000004', '33333333-0206-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is the distance between (2, 5) and (2, -1)?', NULL, NULL, '"6"'::jsonb, 'Same x = vertical distance: |5 - (-1)| = |5 + 1| = 6.', 'Same x means just count the vertical gap', 5, 4),
('44444444-0206-0003-0001-000000000005', '33333333-0206-0001-0001-000000000003', 'multiple_choice', 'medium', 'What is the distance between (0, 0) and (5, 12)?', NULL, '[{"id":"a","text":"17"},{"id":"b","text":"13"},{"id":"c","text":"60"},{"id":"d","text":"7"}]'::jsonb, '"b"'::jsonb, '√(5² + 12²) = √(25 + 144) = √169 = 13. The 5-12-13 is another classic Pythagorean triple!', 'Pythagorean theorem: √(5² + 12²)', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0206-0001-0001-000000000004', '22222222-0002-0001-0001-000000000006', 'Coordinate Plane Boss', 'Show your mastery of the coordinate plane!', 4, 'boss_round', 25, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0206-0004-0001-000000000001', '33333333-0206-0001-0001-000000000004', 'fill_in_blank', 'medium', 'If you reflect the point (3, -7) across the y-axis, what is the new x-coordinate?', NULL, NULL, '"-3"'::jsonb, 'Reflecting across the y-axis flips the x-coordinate: (3, -7) becomes (-3, -7).', 'Y-axis reflection changes the sign of x', 10, 1),
('44444444-0206-0004-0001-000000000002', '33333333-0206-0001-0001-000000000004', 'multiple_choice', 'medium', 'A rectangle has corners at (1, 1), (1, 5), (4, 5), and (4, 1). What is its area?', NULL, '[{"id":"a","text":"8"},{"id":"b","text":"12"},{"id":"c","text":"14"},{"id":"d","text":"20"}]'::jsonb, '"b"'::jsonb, 'Width = 4 - 1 = 3. Height = 5 - 1 = 4. Area = 3 × 4 = 12 square units.', 'Find the width and height from the coordinates', 10, 2),
('44444444-0206-0004-0001-000000000003', '33333333-0206-0001-0001-000000000004', 'fill_in_blank', 'medium', 'What is the midpoint of (2, 8) and (6, 4)? Give the x-coordinate. (Type just the number)', NULL, NULL, '"4"'::jsonb, 'Midpoint x = (2 + 6) / 2 = 8 / 2 = 4. The midpoint formula averages the coordinates.', 'Average the two x-values', 10, 3),
('44444444-0206-0004-0001-000000000004', '33333333-0206-0001-0001-000000000004', 'true_false', 'medium', 'True or False: The points (2, 3), (5, 3), and (8, 3) all lie on the same horizontal line.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! All three points have y = 3. Points with the same y-value form a horizontal line.', 'What do all three y-values have in common?', 10, 4),
('44444444-0206-0004-0001-000000000005', '33333333-0206-0001-0001-000000000004', 'multiple_choice', 'medium', 'The word "Cartesian" in "Cartesian plane" comes from:', NULL, '[{"id":"a","text":"The Latin name for coordinates"},{"id":"b","text":"The Latinized form of Descartes''s name"},{"id":"c","text":"An ancient Greek word for grid"},{"id":"d","text":"The French word for plane"}]'::jsonb, '"b"'::jsonb, 'Cartesian comes from Cartesius, the Latin form of "Descartes." The coordinate plane is literally named after him.', 'Think about whose name sounds like "Cartesian"', 10, 5)
